from test import support
maxsize = support.MAX_Py_ssize_t

def _t():

    class _SelfNS:
        pass
    self = _SelfNS()
    self.pos = 2 ** 100
    self.neg = -self.pos

    class GetItem:

        def __len__(self):
            assert False, '__len__ should not be invoked'

        def __getitem__(self, key):
            return key
    x = GetItem()
    assert x[self.pos] == self.pos, ('assertEqual', x[self.pos], self.pos)
    assert x[self.neg] == self.neg, ('assertEqual', x[self.neg], self.neg)
